class SuperClass {
    public static void printMessage() {
        System.out.println("Static method in SuperClass");
    }
}

class SubClass extends SuperClass {
    // COMPILE-TIME ERROR: attempting to assign weaker access privileges
    // or attempting to override a static method with an instance method.
    /*
    @Override
    public void printMessage() {
        System.out.println("Attempting to make it non-static");
    }
    */

    // Correct approach if you want method hiding (both static):
    public static void printMessage() {
        System.out.println("Hidden static method in SubClass");
    }
}

public class TestDriver {
    public static void main(String[] args) {
        SuperClass.printMessage(); // Outputs: Static method in SuperClass
        SubClass.printMessage();   // Outputs: Hidden static method in SubClass

        SuperClass ref = new SubClass();
        ref.printMessage(); // Outputs: Static method in SuperClass (Resolved via reference type, not object type)
    }
}
